/* Types */
/**  一个 agent 的完整可编辑配置（Rust → 前端）。 */
export type AgentConfig = {
	/**  稳定 id（`claude` / `opencode` / `codex` / `pi`）。 */
	id: string,
	/**  菜单、页签与设置页显示的名称。 */
	name: string,
	/**  可执行命令（只填程序；参数放 [`Self::args`]）。 */
	command: string,
	/**  原样追加在命令后的参数串（例如 `--model sonnet`）。 */
	args: string,
	/**  图标颜色（十六进制，如 `#d97757`）。 */
	color: string,
};

/**  状态事实来源。 */
export type AgentStatusSource = 
/**  agent 原生事件。 */
"native" | 
/**  进程退出事实。 */
"process" | 
/**  降级启发式（#81 预留）。 */
"heuristic";

/**  前端看到的状态枚举（与 `ageminal_agent::AgentState` 一一对应）。 */
export type AgentStatusState = 
/**  运行中。 */
"running" | 
/**  回合完成。 */
"done" | 
/**  空闲。 */
"idle" | 
/**  等待输入。 */
"waiting" | 
/**  等待授权。 */
"permission" | 
/**  出错。 */
"error" | 
/**  进程已退出。 */
"exited";

/**
 *  给前端的版本化状态快照（#80）。
 * 
 *  `timestampMs` / `seq` 用 `f64`：specta 不生成 `u64`（BigInt 精度）；Unix 毫秒与
 *  agent 序号都远小于 2^53。
 */
export type AgentStatusView = {
	/**  逻辑会话 id。 */
	sid: string,
	/**  agent id。 */
	agent: string | null,
	/**  本次 spawn 的世代 id。 */
	incarnationId: string | null,
	/**  统一状态。 */
	state: AgentStatusState,
	/**  事实来源。 */
	source: AgentStatusSource,
	/**  降级启发式 / 状态不完整（#81）；UI 据此显示「状态不完整」。 */
	degraded: boolean,
	/**  事件时间（Unix 毫秒）。 */
	timestampMs: number | null,
	/**  逻辑序号；0 = 无。 */
	seq: number | null,
	/**  非零退出码（仅 `exited`）。 */
	exitCode: number | null,
	/**  最近错误原因。 */
	reason: string | null,
};

/**  应用与运行时的基础信息。 */
export type AppInfo = {
	/**  产品名。 */
	name: string,
	/**  应用版本（单一来源 = 根 package.json）。 */
	version: string,
	/**  运行平台（`std::env::consts::OS`）。 */
	os: string,
};

/**  目录里的一个条目（与 `ageminal-files::Entry` 字段一一对应）。 */
export type DirEntryView = {
	/**  文件名。 */
	name: string,
	/**  绝对路径。 */
	path: string,
	/**  是否目录。 */
	isDir: boolean,
	/**  维度 2：dotfile（名字以 `.` 开头）。 */
	hidden: boolean,
	/**  维度 3：被忽略规则命中（`.gitignore` / `.git/info/exclude` / 全局 excludes）。 */
	ignored: boolean,
};

/**  一个目录的列举结果。 */
export type DirListingView = {
	entries: DirEntryView[],
	/**  条目数超过单目录上限（5000），已截断。 */
	truncated: boolean,
};

