/**  集成状态（设置页五态）。 */
export type IntegrationStatus = 
/**  未启用（没有任何 Ageminal 注入物）。 */
"notEnabled" | 
/**  全部当前版本。 */
"enabled" | 
/**  文件已存在但内容落后 / 路径变化。 */
"updateAvailable" | 
/**  只有部分文件成功 / 存在。 */
"partial" | 
/**  该 agent 不走本框架（Codex 归 #84，dsh 不支持）。 */
"unsupported";

